/**
 * Error type exposed to Kotlin via UniFFI
 */
sealed class VoiceCoreException: kotlin.Exception() {
    
    class Database(
        
        val `msg`: kotlin.String
        ) : VoiceCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Config(
        
        val `msg`: kotlin.String
        ) : VoiceCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Sync(
        
        val `msg`: kotlin.String
        ) : VoiceCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Validation(
        
        val `msg`: kotlin.String
        ) : VoiceCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Io(
        
        val `msg`: kotlin.String
        ) : VoiceCoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<VoiceCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): VoiceCoreException = FfiConverterTypeVoiceCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeVoiceCoreError : FfiConverterRustBuffer<VoiceCoreException> {
    override fun read(buf: ByteBuffer): VoiceCoreException {
        

        return when(buf.getInt()) {
            1 -> VoiceCoreException.Database(
                FfiConverterString.read(buf),
                )
            2 -> VoiceCoreException.Config(
                FfiConverterString.read(buf),
                )
            3 -> VoiceCoreException.Sync(
                FfiConverterString.read(buf),
                )
            4 -> VoiceCoreException.Validation(
                FfiConverterString.read(buf),
                )
            5 -> VoiceCoreException.Io(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: VoiceCoreException): ULong {
        return when(value) {
            is VoiceCoreException.Database -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VoiceCoreException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VoiceCoreException.Sync -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VoiceCoreException.Validation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VoiceCoreException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: VoiceCoreException, buf: ByteBuffer) {
        when(value) {
            is VoiceCoreException.Database -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VoiceCoreException.Config -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VoiceCoreException.Sync -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VoiceCoreException.Validation -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VoiceCoreException.Io -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * The phone's Keystore (Stage 14): wraps a secret before the core writes
 * it and unwraps it after the core reads it. The clear bytes live in memory only.
 */
public interface KeystoreWrapper {
    
    fun `wrap`(`clear`: kotlin.ByteArray): kotlin.ByteArray
    
    fun `unwrap`(`wrapped`: kotlin.ByteArray): kotlin.ByteArray
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceKeystoreWrapper {
    internal object `wrap`: UniffiCallbackInterfaceKeystoreWrapperMethod0 {
        override fun callback(`uniffiHandle`: Long,`clear`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeKeystoreWrapper.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`wrap`(
                    FfiConverterByteArray.lift(`clear`),
                )
            }
            val writeReturn = { value: kotlin.ByteArray -> uniffiOutReturn.setValue(FfiConverterByteArray.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `unwrap`: UniffiCallbackInterfaceKeystoreWrapperMethod1 {
        override fun callback(`uniffiHandle`: Long,`wrapped`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeKeystoreWrapper.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`unwrap`(
                    FfiConverterByteArray.lift(`wrapped`),
                )
            }
            val writeReturn = { value: kotlin.ByteArray -> uniffiOutReturn.setValue(FfiConverterByteArray.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeKeystoreWrapper.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceKeystoreWrapper.UniffiByValue(
        `wrap`,
        `unwrap`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_voicecore_fn_init_callback_vtable_keystorewrapper(vtable)
    }
}

